*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */

        /*달력셋팅*/

        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf30001.onpageload' }); }
};

// [A] 초기 목록 미해결 — 같은 액션인데 method 가 2개다(strip#searchstripobjlist vs strip#savestripnew) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dmenus = undefined; try { scwin.dmenus = /* sdd-asis-lifecycle:begin dmenus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */{
        "bmenu":5
        ,"mmenu":9
    }/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf30001' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_datefmt_cal_procsReqDd();
        scwin.init_datefmt_cal_bndFstSprtDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldbnf30001.onpageload' });
    }
};


