        (($c.util.getComponent('txt_sprtParAmtKor') && $c.util.getComponent('txt_sprtParAmtKor').setValue) ? $c.util.getComponent('txt_sprtParAmtKor').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, ''))) : console.warn('[sdd] num2won 대상 미해결: ' + 'sprt_par_amt_kor'));
        /* sdd-asis-lifecycle:end */

